+func renderWhyBlockRow(block whyBlock, width int) string {
+	var lines []string
+
+	head := strings.TrimSpace(strings.Join([]string{
+		block.RangeText(),
+		shortWhyBlockCommit(block.Commit),
+		block.Commit.Author,
+	}, "  "))
+	lines = append(lines, truncateWhyText(head, width))
+
+	if block.Entire != nil {
+		entireLine := strings.TrimSpace(strings.Join([]string{
+			block.Entire.CheckpointID,
+			block.Entire.Agent,
+		}, "  "))
+		if entireLine != "" {
+			lines = append(lines, truncateWhyText(entireLine, width))
+		}
+		if block.Entire.Summary != "" {
+			lines = append(lines, truncateWhyText(block.Entire.Summary, width))
+		}
+	} else if block.Commit.Subject != "" {
+		lines = append(lines, truncateWhyText(block.Commit.Subject, width))
+	}
+
+	return strings.Join(lines, "\n")
+}
