+	code := strings.Join(block.CodeLines, "\n")
+	if code == "" {
+		b.WriteString(m.styles.render(m.styles.dim, "No source available."))
+		return b.String()
+	}
+
+	b.WriteString(renderWhyHighlightedCode(m.path, code))
+	return strings.TrimRight(b.String(), "\n")
+}
+
+func renderWhyHighlightedCode(path, code string) string {
+	if strings.TrimSpace(code) == "" {
+		return code
+	}
+
+	styleName := "dracula"
+	if styles.Get(styleName) == nil {
+		styleName = "monokai"
+	}
+
+	formatter := "terminal256"
+	if formatters.Get(formatter) == nil {
+		return code
+	}
+
+	lexer := lexers.Match(path)
+	if lexer == nil {
+		lexer = lexers.Match(filepath.Base(path))
+	}
+	if lexer == nil {
+		lexer = lexers.Analyse(code)
+	}
+	if lexer == nil {
+		return code
+	}
+
+	var b strings.Builder
+	if err := quick.Highlight(&b, code, lexer.Config().Name, formatter, styleName); err != nil {
+		return code
+	}
+
+	return strings.TrimRight(b.String(), "\n")
